"""Counting integers with a prescribed suffix and digit limit."""


def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count positive integers in [start, finish] with suffix s and digits <= limit.

    A matching integer has the form prefix * 10**len(s) + int(s).
    Count the permitted prefixes up to each endpoint using a digit scan.
    Time and auxiliary space are O(log(finish)).
    """
    if start > finish:
        return 0
    if not s or any(ch not in "0123456789" for ch in s):
        raise ValueError("s must be a nonempty decimal string")
    if not 1 <= limit <= 9:
        raise ValueError("limit must be between 1 and 9")
    if any(int(ch) > limit for ch in s):
        return 0

    suffix = int(s)
    scale = 10 ** len(s)
    radix = limit + 1

    def count_up_to(bound: int) -> int:
        if bound <= 0 or bound < suffix:
            return 0
        maximum_prefix = (bound - suffix) // scale
        digits = str(maximum_prefix)
        place_count = radix ** (len(digits) - 1)
        total = 0
        for ch in digits:
            digit = int(ch)
            total += min(digit, radix) * place_count
            if digit > limit:
                break
            place_count //= radix
        else:
            total += 1  # Include maximum_prefix itself.

        # With no prefix, leading zeroes do not appear in a positive integer.
        if s[0] == "0":
            total -= 1
        return total

    return count_up_to(finish) - count_up_to(start - 1)

