from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th positive amount divisible by at least one denomination.

    Remove redundant denominations, then binary-search using LCM-aggregated
    inclusion-exclusion counts. The caller's list is not modified.
    """
    if k < 1:
        raise ValueError("k must be positive")
    denominations = sorted(set(coins))
    if not denominations or denominations[0] <= 0:
        raise ValueError("coins must contain positive denominations")

    essential = []
    for coin in denominations:
        if all(coin % smaller != 0 for smaller in essential):
            essential.append(coin)
    if len(essential) == 1:
        return essential[0] * k

    upper = essential[0] * k
    coefficients = {}
    for coin in essential:
        additions = {coin: 1} if coin <= upper else {}
        for previous_lcm, coefficient in coefficients.items():
            combined = lcm(previous_lcm, coin)
            if combined <= upper:
                additions[combined] = additions.get(combined, 0) - coefficient
        for multiple, coefficient in additions.items():
            updated = coefficients.get(multiple, 0) + coefficient
            if updated:
                coefficients[multiple] = updated
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())

    def count_at_most(amount: int) -> int:
        return sum(coefficient * (amount // multiple)
                   for multiple, coefficient in terms)

    lower = essential[0]
    while lower < upper:
        middle = (lower + upper) // 2
        if count_at_most(middle) >= k:
            upper = middle
        else:
            lower = middle + 1
    return lower

from typing import List


def min_absolute_difference(nums: List[int], k: int) -> int:
    """Return the minimum absolute difference between k and a subarray OR.

    Keep the distinct OR values for subarrays ending at the current position.
    Time is O(len(nums) * W), space O(W), where W is the integer bit width.
    The input list is not modified.
    """
    if not nums:
        raise ValueError("nums must be nonempty")
    best = abs(nums[0] - k)
    endings = set()
    for number in nums:
        endings = {number} | {value | number for value in endings}
        for value in endings:
            difference = abs(value - k)
            if difference == 0:
                return 0
            if difference < best:
                best = difference
    return best

from functools import cache


def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count integers with equally many even/odd digits and divisible by k.

    Leading zeroes are excluded from the digit counts, while internal zeroes
    count as even digits. Subtract digit-DP counts at the two endpoints.
    For d decimal digits, time is O(10 * k * d**2), space O(k * d**2).
    """
    if k <= 0:
        raise ValueError("k must be positive")
    if low > high:
        return 0

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))
        length = len(digits)

        @cache
        def visit(position: int, remainder: int, balance: int,
                  started: bool, tight: bool) -> int:
            remaining = length - position
            if started and (abs(balance) > remaining or (balance + remaining) % 2):
                return 0
            if position == length:
                return int(started and remainder == 0 and balance == 0)

            ceiling = digits[position] if tight else 9
            total = 0
            for digit in range(ceiling + 1):
                next_tight = tight and digit == digits[position]
                if not started and digit == 0:
                    total += visit(position + 1, 0, 0, False, next_tight)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    total += visit(position + 1, (remainder * 10 + digit) % k,
                                   next_balance, True, next_tight)
            return total

        return visit(0, 0, 0, False, True)

    return count_up_to(high) - count_up_to(low - 1)

