"""Independent deterministic validation, plus an optional supplied-test audit.

Run:
    python validate_components.py
    python validate_components.py --audit-supplied

The second command also reports discrepancies against the unmodified supplied
expectations in supplied_test_cases.json and exits nonzero if any remain.
"""

import argparse
import json
from itertools import product
from pathlib import Path
from random import Random

from count_powerful_integers import count_powerful_integers
from count_valid_colorings import count_valid_colorings
from calculate_black_area_doubled import calculate_black_area_doubled
from kth_smallest_amount import kth_smallest_amount
from min_absolute_difference import min_absolute_difference
from count_beautiful_integers import count_beautiful_integers

FUNCTIONS = {
    function.__name__: function
    for function in (
        count_powerful_integers, count_valid_colorings,
        calculate_black_area_doubled, kth_smallest_amount,
        min_absolute_difference, count_beautiful_integers,
    )
}


def validate():
    rng = Random(20260410)
    counts = dict.fromkeys(FUNCTIONS, 0)

    def check(name, arguments, expected):
        actual = FUNCTIONS[name](*arguments)
        assert actual == expected, (name, arguments, expected, actual)
        counts[name] += 1

    for limit in range(1, 10):
        for suffix in ("1", "2", "9", "10", "11", "49", "101", "010", "00", "0"):
            expected = 0
            for upper in range(1, 351):
                text = str(upper)
                expected += text.endswith(suffix) and all(int(c) <= limit for c in text)
                check("count_powerful_integers", (1, upper, limit, suffix), expected)
    for _ in range(200):
        low = rng.randint(1, 5000)
        high = rng.randint(low, 6000)
        limit = rng.randint(1, 9)
        suffix = str(rng.randint(1, 300))
        expected = sum(str(x).endswith(suffix) and all(int(c) <= limit for c in str(x))
                       for x in range(low, high + 1))
        check("count_powerful_integers", (low, high, limit, suffix), expected)

    for n in range(2, 8):
        for m in range(2, 5):
            expected = sum(all(colors[i] != colors[(i + 1) % n] for i in range(n))
                           for colors in product(range(m), repeat=n))
            check("count_valid_colorings", (n, m), expected)

    def geometric_square(x, y):
        # The two equal-area triangles have centroids at offsets 1/3 and 2/3.
        # Crossing any defining line changes the parity below. Integer-scaled
        # floors avoid floating-point errors, including at negative coordinates.
        return sum((x + (3 * y + t) // 6 + (3 * (x + y) + 2 * t) // 6) % 2 == 0
                   for t in (1, 2))

    for a in range(-4, 4):
        for c in range(a + 1, 5):
            for b in range(-4, 4):
                for d in range(b + 1, 5):
                    expected = sum(geometric_square(x, y)
                                   for x in range(a, c) for y in range(b, d))
                    check("calculate_black_area_doubled", (a, b, c, d), expected)
    check("calculate_black_area_doubled", (-10**9, -10**9, 10**9, 10**9), 4 * 10**18)
    for _ in range(100):
        a, b = rng.randint(-10**9, 10**9 - 100), rng.randint(-10**9, 10**9 - 100)
        c, d = a + rng.randint(1, 100), b + rng.randint(1, 100)
        area = calculate_black_area_doubled(a, b, c, d)
        check("calculate_black_area_doubled", (a + 2, b, c + 2, d),
              2 * (c - a) * (d - b) - area)
        check("calculate_black_area_doubled", (a + 4, b + 2, c + 4, d + 2), area)

    for _ in range(500):
        coins = rng.sample(range(1, 26), rng.randint(1, 15))
        original = coins[:]
        k = rng.randint(1, 150)
        upper = min(coins) * k
        amounts = sorted({coin * multiple for coin in coins
                          for multiple in range(1, upper // coin + 1)})
        check("kth_smallest_amount", (coins, k), amounts[k - 1])
        assert coins == original
    check("kth_smallest_amount", ([25], 2_000_000_000), 50_000_000_000)
    check("kth_smallest_amount", ([1, 10, 100, 1000, 10000], 2_000_000_000), 2_000_000_000)

    def brute_or(nums, target):
        best = float("inf")
        for start in range(len(nums)):
            value = 0
            for end in range(start, len(nums)):
                value |= nums[end]
                best = min(best, abs(value - target))
        return best

    for length in range(1, 5):
        for values in product(range(1, 5), repeat=length):
            for target in range(1, 16):
                check("min_absolute_difference", (list(values), target), brute_or(values, target))
    for _ in range(1000):
        nums = [rng.randint(1, 10**9) for _ in range(rng.randint(1, 20))]
        original = nums[:]
        target = rng.randint(1, 10**9)
        check("min_absolute_difference", (nums, target), brute_or(nums, target))
        assert nums == original

    def balanced(number):
        text = str(number)
        return sum(int(digit) % 2 == 0 for digit in text) * 2 == len(text)

    flags = [False] + [balanced(number) for number in range(1, 4001)]
    for divisor in range(1, 21):
        prefix = [0]
        for number in range(1, 4001):
            prefix.append(prefix[-1] + (flags[number] and number % divisor == 0))
        for upper in range(1, 101):
            check("count_beautiful_integers", (1, upper, divisor), prefix[upper])
        for _ in range(50):
            low = rng.randint(1, 4000)
            high = rng.randint(low, 4000)
            check("count_beautiful_integers", (low, high, divisor), prefix[high] - prefix[low - 1])
    for _ in range(100):
        low = rng.randint(1, 1_000_000)
        high = low + rng.randint(0, 500)
        divisor = rng.randint(1, 20)
        expected = sum(number % divisor == 0 and balanced(number) for number in range(low, high + 1))
        check("count_beautiful_integers", (low, high, divisor), expected)

    for name, total in counts.items():
        print(f"{name}: {total} independent checks passed")
    print(f"TOTAL: {sum(counts.values())} independent checks passed")
    return counts


def audit_supplied(cases):
    failures = []
    total = 0
    for name, entries in cases.items():
        for arguments, expected in entries:
            total += 1
            actual = FUNCTIONS[name](*arguments)
            if actual != expected:
                failure = {"function": name, "arguments": arguments,
                           "supplied_expected": expected, "actual": actual}
                failures.append(failure)
                print(json.dumps(failure))
    print(f"Supplied test audit: {total - len(failures)}/{total} expectations matched; "
          f"{len(failures)} discrepancies")
    return failures


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--audit-supplied", action="store_true")
    args = parser.parse_args()
    validate()
    if args.audit_supplied:
        data = json.loads(Path(__file__).with_name("supplied_test_cases.json").read_text())
        if audit_supplied(data):
            raise SystemExit(1)

